mapper.select:
	select busi_date from (
	  select h.busi_date from CHB_MKT_HOLIDAY h
	  where h.busi_date < #{busi_date}
		and h.is_holiday = #{is_holiday}
		and h.market_code = #{market_code}
	  order by h.busi_date desc
  	) where rownum = 1

	select busi_date from (
	  select h.busi_date from CHB_MKT_HOLIDAY h
	  where h.busi_date > #{busi_date}
		and h.is_holiday = #{is_holiday}
		and h.market_code = #{market_code}
	  order by h.busi_date
  	) where rownum = 1
